/**
 * Base fields present on every record in the system.
 * Apps define payloads that extend this via `Record<P>`.
 */
export interface BaseRecord {
  /** UUID v4, generated by the Store on insertion */
  id: string;
  /** ISO 8601 timestamp, generated by the Store on insertion */
  createdAt: string;
  /** The device that created this record */
  deviceId: string;
  /** Name of the collection this record belongs to, set from the collection key */
  collection: string;
}

/**
 * A full record: base fields plus an app-defined typed payload.
 */
export type Record<P> = BaseRecord & { payload: P };

/**
 * Internal Dexie row type. Adds the sync outbox status field.
 * This type is never exposed to apps — the Store strips `_syncStatus`
 * from all values returned through the public API.
 */
export interface SyncedRow<P> extends Record<P> {
  _syncStatus: 'pending' | 'synced';
}

/**
 * A collections map: each key is a collection name, each value is the
 * payload type for that collection. Apps define this as a type, e.g.
 *
 *   type KhataCollections = {
 *     customers: { name: string; phone?: string };
 *     transactions: { customerId: string; amount: number };
 *   };
 *
 * Note: use `type` not `interface` so the generic constraints resolve cleanly.
 */
export type Collections = { [key: string]: any };

/**
 * Helper: extract the payload type for a specific collection.
 */
export type CollectionPayload<C, K extends keyof C> = C[K];

/**
 * Helper: convert a Collections interface into a map of
 * collection name → Record<P>.
 */
export type CollectionRecords<C> = {
  [K in keyof C]: Record<C[K]>;
};

/**
 * Helper: convert a Collections interface into a map of
 * collection name → SyncedRow<P>.
 */
export type CollectionSyncedRows<C> = {
  [K in keyof C]: SyncedRow<C[K]>;
};
